"""Write the Results section of docs/EXPERIMENTS.md from the CSV/JSON outputs (no hand-copied numbers)."""
import json, os
import pandas as pd

ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..")
R = os.path.join(ROOT, "results")
SHORT = {"mobilenetv3_small_100": "MobileNetV3-Small", "mobilenetv3_large_100": "MobileNetV3-Large", "efficientnet_b0": "EfficientNet-B0", "efficientnet_lite0": "EfficientNet-Lite0"}
f = lambda x, n=3: "" if pd.isna(x) else f"{x:.{n}f}"
out = ["## 7. Results", "", "All tables are generated by `scripts/make_results_md.py` from `results/*.csv`. Test set = 202 BRACOL images per split; "
       "means are over 3 random stratified splits (seeds 42, 1, 2). **SYNTHETIC ROBUSTNESS TEST is not field validation.**", ""]

S1 = pd.read_csv(os.path.join(R, "model_selection.csv")).set_index("arch")
out += ["### 7.1 Phase 1 — clean-trained architectures (pre-registered rule, section 6)", "",
        "| Model | Params (M) | Accuracy | Macro-F1 | FP32 ONNX (MB) | INT8 ONNX (MB) / macro-F1 drop (pts, Python ORT) | Browser latency ms (x1 / x4 / x6 throttle, emulated) | Coverage @HIGH | Selective acc @HIGH | Selective acc @80% coverage | Robustness (mean macro-F1, 10 perturbations) | Score | Rank | Top-1 in N of 3 seeds |",
        "|---|---|---|---|---|---|---|---|---|---|---|---|---|---|"]
for a, r in S1.iterrows():
    out.append(f"| {SHORT[a]} | {r.params_M:.2f} | {r.acc_mean:.3f} +/- {r.acc_sd:.3f} | {r.macro_f1_mean:.3f} +/- {r.macro_f1_sd:.3f} | {r.onnx_fp32_MB:.1f} | {r.onnx_int8_MB:.1f} / {r['int8_macro_f1_drop_pts(py-ort)']:.1f} | {r.lat_ms_x1:.0f} / {r.lat_ms_x4:.0f} / {r.lat_ms_x6:.0f} | {r.cov_hi:.3f} | {r.sel_acc_hi:.3f} | {r.sel_acc_at_80cov:.3f} | {r.robust_macro_f1:.3f} | {r.score:.3f} | {int(r['rank'])} | {int(r.top1_in_seeds_of_3)} |")
out += ["", "INT8 (static QDQ) was **rejected** for every candidate: INT8 macro-F1 dropped by more than 3 points, INT8 was *slower* than FP32 in the browser (e.g. "
        + ", ".join(f"{SHORT[a]} {S1.loc[a, 'lat_ms_x1']:.0f} -> {S1.loc[a, 'lat_int8_ms_x1']:.0f} ms" for a in S1.index)
        + "), and onnxruntime-web INT8 logits differed from onnxruntime Python by up to 11 (argmax agreement on 8 held-out images: "
        + ", ".join(f"{SHORT[a]} {S1.loc[a, 'int8_browser_parity_agree']}" for a in S1.index) + "). FP32 ONNX/browser parity was exact (max abs logit diff < 8e-4, 8/8).", "",
        f"Sensitivity: with 5,000 random weight vectors around the pre-registered ones, win shares were "
        + ", ".join(f"{SHORT[a]} {S1.loc[a, 'win_share_random_weights']:.2f}" for a in S1.index) + ". **Quality differences between architectures are within seed noise** (SD up to 0.038 macro-F1); the Phase 1 choice was driven by edge cost.", ""]

D = pd.read_csv(os.path.join(R, "phase2_recipe_decision_validation.csv"))
out += ["### 7.2 Phase 2 (post-hoc) — robust augmentation", "", "Criterion frozen in section 6c. Decision on **seed-42 validation** data:", "",
        "| Model | Val clean F1 (clean / robust) | Val perturbed F1 (clean / robust) | Delta perturbed | Adopt robust recipe |", "|---|---|---|---|---|"]
for _, r in D.iterrows():
    out.append(f"| {SHORT[r.arch]} | {r.val_clean_f1_phase1:.3f} / {r.val_clean_f1_phase2:.3f} | {r.val_pert_f1_phase1:.3f} / {r.val_pert_f1_phase2:.3f} | {r.delta_pert:+.3f} | {'yes' if r.adopt_robust else 'no'} |")
C = pd.read_csv(os.path.join(R, "phase2_comparison.csv"))
out += ["", "Test, mean of 3 splits (phase 1 clean-trained -> phase 2 robust-trained). Perturbations are the same *families* as the training augmentation, so gains are **in-family**:", "",
        "| Model | Clean macro-F1 | Mean perturbed macro-F1 | `combined` F1 | `bg_clutter` F1 | `bg_uniform` F1 (diagnostic) | Model-only confident-wrong rate on perturbations |", "|---|---|---|---|---|---|---|"]
for a in SHORT:
    p1, p2 = C[(C.arch == a) & (C.phase == 1)].iloc[0], C[(C.arch == a) & (C.phase == 2)].iloc[0]
    out.append(f"| {SHORT[a]} | {p1.macro_f1:.3f} -> {p2.macro_f1:.3f} | {p1.robust_f1:.3f} -> {p2.robust_f1:.3f} | {p1.combined_f1:.3f} -> {p2.combined_f1:.3f} | {p1.bg_clutter_f1:.3f} -> {p2.bg_clutter_f1:.3f} | n/a -> {p2.bg_uniform_f1:.3f} | {p1.conf_wrong:.3f} -> {p2.conf_wrong:.3f} |")
S2 = pd.read_csv(os.path.join(R, "model_selection_rob.csv")).set_index("arch")
out += ["", "Phase 2 selection (same weighted rule, same edge terms): " + ", ".join(f"{SHORT[a]} {S2.loc[a, 'score']:.3f} (rank {int(S2.loc[a, 'rank'])})" for a in S2.index)
        + ". **Shipped: MobileNetV3-Large (robust).** Honest note: its clean macro-F1 is within noise of MobileNetV3-Small, which is 2.8x smaller and faster; the pre-registered rule favours Large through its robustness and calibration terms (min-max normalisation amplifies small differences).", ""]

G = json.load(open(os.path.join(R, "guard_summary.json"))); GR = pd.read_csv(os.path.join(R, "guard_results.csv")).set_index("set")
SF = pd.read_csv(os.path.join(R, "system_eval_final.csv")).set_index("condition")
out += ["### 7.3 Input-quality gate and the whole system (shipped model, in-browser metrics)", "",
        "Bounds learned on clean validation only (validation pass rate " + f"{json.load(open(os.path.join(R, 'guard_bounds.json')))['val_pass_rate']:.2f}). "
        "System = gate AND confidence tier HIGH. Per condition, over the 202 test images (`results/system_eval_final.csv`):", "",
        "| Condition | Model macro-F1 | Model HIGH-and-wrong | Gate rejects | System answers | System HIGH-and-wrong | Accuracy on answered |", "|---|---|---|---|---|---|---|"]
for c, r in SF.iterrows():
    out.append(f"| {c} | {r.macro_f1_all:.3f} | {r.model_conf_wrong:.3f} | {r.gate_reject:.3f} | {r.system_answer_rate:.3f} | {r.system_conf_wrong:.3f} | {f(r.system_answer_accuracy)} |")
out += ["", f"Averaged over the 10 fixed perturbations: model-only confident-wrong {SF.drop(['clean', 'bg_uniform']).model_conf_wrong.mean():.3f} -> system {SF.drop(['clean', 'bg_uniform']).system_conf_wrong.mean():.3f}, "
        f"at the price of the gate refusing {SF.drop(['clean', 'bg_uniform']).gate_reject.mean():.0%} of them (and {SF.loc['clean', 'gate_reject']:.1%} of clean images). "
        "**With robust training the model alone is already fairly safe on these perturbations, so the gate is now mostly a scope guard** (it also refuses plain grey backgrounds and high-contrast images that the model handles: over-specific, tuned to BRACOL captures).", "",
        f"External field photos (Uganda + RoCoLe, {G['external_pooled']['n']} images): the gate rejects {G['external_pooled']['gate_reject_rate']:.0%}. RoCoLe rejections are real out-of-protocol backgrounds (busy 100%, colourful 94%); Uganda rejections are partly a resolution artefact (256 px images upscaled, so a sharpness check fails). The gate is **resolution dependent**.", ""]

ext = os.path.join(R, "external_eval_rob.csv")
if os.path.exists(ext):
    E = pd.read_csv(ext)
    u = E[(E.dataset == "uganda")].iloc[0:2]; r = E[(E.dataset == "rocole")].iloc[0:2]
    out += ["### 7.4 External field data, final model (model alone, thresholds from clean BRACOL validation; image padded to 2:1 or stretched)", "",
            "| Dataset | Preprocessing | Accuracy / macro-F1 (3 classes) or AUROC | Recall healthy / rust (/ phoma) | HIGH-tier coverage | Notes |", "|---|---|---|---|---|---|"]
    for _, x in u.iterrows():
        out.append(f"| Uganda (n={int(x.n)}, ~{int(x.approx_unique_originals)} unique) | {x['mode']} | {x.accuracy:.3f} / {x.macro_f1_3class:.3f} | {x.recall_healthy:.2f} / {x.recall_rust:.2f} / {x.recall_phoma:.2f} | {x.coverage_high:.2f} (acc {x.sel_acc_high:.2f}) | chance for 3 classes = 0.33 |")
    for _, x in r.iterrows():
        out.append(f"| RoCoLe (n={int(x.n)}) | {x['mode']} | AUROC rust vs healthy {x.auroc_rust_vs_healthy:.3f} | {x.recall_healthy:.2f} / {x.recall_rust:.2f} | {x.coverage_high:.2f} | red spider mite given a confident disease label: {x.mite_high_conf_disease_rate:.2f} |")
    out.append("")

sp = json.load(open(os.path.join(R, "speech", "mms_results.json"), encoding="utf-8")) if os.path.exists(os.path.join(R, "speech", "mms_results.json")) else None
if sp:
    m = sp["mms300m_waxal_ewe"]; t = sp["mms_tts_ewe"]
    out += ["### 7.5 Ewe speech feasibility (EXPLORATORY: 24 utterances, one corpus, CPU)", "",
            "Eval set: WAXAL Ewe ASR test shard 1 (human transcriptions, spontaneous image-prompted speech, CC-BY / CC-BY-SA). Only the smallest Ewe MMS-based model was benchmarked; "
            "the 1B-parameter models (`facebook/mms-1b-all` 965M params / 3.86 GB; community adapters on the same base) were **not** benchmarked because size alone rules them out. Their self-reported scores are unverified.", "",
            "| System | Params | FP32 size | WER | CER | CPU RTF (6 threads) | Notes |", "|---|---|---|---|---|---|---|",
            f"| MMS-300M fine-tuned on WAXAL Ewe (community, CC-BY-NC-4.0) | {m['params'] / 1e6:.0f} M | {m['fp32_MB']:.0f} MB | {m['fp32']['wer']:.3f} | {m['fp32']['cer']:.3f} | {m['fp32']['rtf_cpu6']:.2f} | peak RSS ~{m['fp32']['peak_rss_MB'] / 1000:.1f} GB; model card claims WER 31.3 / CER 9.6 on WAXAL test |",
            f"| same, dynamic INT8 (Linear layers) | | {m['dynamic_int8']['state_dict_MB']:.0f} MB | {m['dynamic_int8']['wer']:.3f} | {m['dynamic_int8']['cer']:.3f} | {m['dynamic_int8']['rtf_cpu6']:.2f} | still ~60x our vision model |",
            f"| MMS-TTS Ewe (Meta, CC-BY-NC-4.0) | {t['params'] / 1e6:.1f} M | {t['fp32_MB']:.0f} MB | n/a | n/a | {sum(s['rtf'] for s in t['samples']) / len(t['samples']):.2f} | quality needs a native speaker; 5 samples in `results/speech/tts_samples/` |", "",
            "**Decision: Ewe voice input is not embedded.** Text Ewe stays in P0 (translations to be supplied by a native speaker). A feasible route is *pre-generated* audio of the fixed answers from validated Ewe text. ONNX export of the 300M model was not tested (missing `onnxscript` in the environment), so ONNX feasibility is inconclusive, not negative. "
            "Umbaji's `Umbaji/Yodi` (Ewe+English ASR, Keras `.h5`) is gated (manual approval) and CC-BY-NC-3.0, so it could not be benchmarked.", ""]

p = os.path.join(ROOT, "docs", "EXPERIMENTS.md"); s = open(p, encoding="utf-8").read()
i = s.index("## 7. Results"); s = s[:i] + "\n".join(out) + "\n"
open(p, "w", encoding="utf-8").write(s); print("EXPERIMENTS.md results written,", len(out), "lines")
